                        :description => "Determines whether or not this image is visible.",
                        :dflt => true,
                        :editType => arraydraw,
                        :valType => boolean,
                    ),
                    :x => D(
                        :description => "Sets the image's x position. When `xref` is set to `paper`, units are sized relative to the plot height. See `xref` for more info",
                        :dflt => 0,
                        :editType => arraydraw,
                        :valType => any,
