            :tickvals => D(
                :description => "Sets the values at which ticks on this axis appear. Only has an effect if `tickmode` is set to *array*. Used with `ticktext`.",
                :editType => ticks,
                :valType => data_array,
            ),
            :tickwidth => D(
                :description => "Sets the tick width (in px).",
                :dflt => 1,
                :editType => ticks,
