                :valType => info_array,
            ),
            :rangebreaks => D(
                :items => D(
                    :rangebreak => D(
                        :bounds => D(
                            :description => "Sets the lower and upper bounds of this axis rangebreak. Can be used with `pattern`.",
                            :editType => calc,
                            :items => Any[
                                D(
                                    :editType => calc,
                                    :valType => any,
                                ),
                                D(
