                :dflt => "-",
                :editType => plot,
                :valType => any,
            ),
            :type => "funnel",
            :uid => D(
                :description => "Assign an id to this trace, Use this to provide object constancy between traces during animations and transitions.",
                :editType => plot,
                :valType => string,
