    :image => D(
        :animatable => false,
        :attributes => D(
            :colormodel => D(
                :description => "Color model used to map the numerical color components described in `z` into colors. If `source` is specified, this attribute will be set to `rgba256` otherwise it defaults to `rgb`.",
