                    :editType => colorbars,
                    :valType => enumerated,
                    :values => ["h", "v"],
                ),
                :outlinecolor => D(
                    :description => "Sets the axis line color.",
                    :dflt => "#444",
                    :editType => colorbars,
                    :valType => color,
                ),
                :outlinewidth => D(
