                        :dflt => "auto",
                        :editType => calc,
                        :valType => angle,
                    ),
                    :tickcolor => D(
                        :description => "Sets the tick color.",
                        :dflt => "#444",
                        :editType => calc,
                        :valType => color,
                    ),
                    :tickfont => D(
