            :xaxes => D(
                :description => "Sets the list of x axes corresponding to dimensions of this splom trace. By default, a splom will match the first N xaxes where N is the number of input dimensions. Note that, in case where `diagonal.visible` is false and `showupperhalf` or `showlowerhalf` is false, this splom trace will generate one less x-axis and one less y-axis.",
                :editType => calc,
                :freeLength => true,
                :items => D(
                    :editType => plot,
                    :regex => "/^x([2-9]|[1-9][0-9]+)?( domain)?\$/",
                    :valType => subplotid,
                ),
                :valType => info_array,
            ),
            :xhoverformat => D(
                :description => "Sets the hover text formatting rule for `x` using d3 formatting mini-languages which are very similar to those in Python. For numbers, see: https://github.com/d3/d3-format/tree/v1.4.5#d3-format. And for dates see: https://github.com/d3/d3-time-format/tree/v2.2.3#locale_format. We add two items to d3's date formatter: *%h* for half of the year as a decimal number as well as *%{n}f* for fractional seconds with n digits. For example, *2016-10-13 09:15:23.456* with tickformat *%H~%M~%S.%2f* would display *09~15~23.46*By default the values are formatted using `xaxis.hoverformat`.",
                :dflt => "",
                :editType => none,
                :valType => string,
            ),
            :yaxes => D(
                :description => "Sets the list of y axes corresponding to dimensions of this splom trace. By default, a splom will match the first N yaxes where N is the number of input dimensions. Note that, in case where `diagonal.visible` is false and `showupperhalf` or `showlowerhalf` is false, this splom trace will generate one less x-axis and one less y-axis.",
                :editType => calc,
                :freeLength => true,
                :items => D(
